// ===========================================================
// AFTER LOAD — URL PARAM AUTO-FILL
// ===========================================================
frappe.web_form.after_load = () => {
    const params = new URLSearchParams(window.location.search);

    const roleParam = params.get("role");
    const locationParam = params.get("location");
    const departmentParam = params.get("department");
    const preferredLocationParam = params.get("preferred_location_options");

    setTimeout(() => {
        if (roleParam) frappe.web_form.set_value("role", decodeURIComponent(roleParam));
        if (locationParam) frappe.web_form.set_value("location", decodeURIComponent(locationParam));
        if (departmentParam) frappe.web_form.set_value("department", decodeURIComponent(departmentParam));

        // Preferred Location — populated only when the job's Apply link carries
        // multiple slash-separated location options (see Job Opening's
        // preferred_location checkbox + _auto_set_job_application_route).
        const prefField = frappe.web_form.fields_dict.preferred_location_form;
        if (prefField) {
            if (preferredLocationParam) {
                const opts = decodeURIComponent(preferredLocationParam).split(",").map(o => o.trim()).filter(Boolean);
                prefField.df.options = ["", ...opts].join("\n");
                prefField.df.hidden = 0;
                prefField.df.reqd = 1;
            } else {
                prefField.df.hidden = 1;
                prefField.df.reqd = 0;
            }
            prefField.refresh();
        }
    }, 300);

    // ===========================================================
    // PHONE + EMAIL OTP VERIFICATION
    // ===========================================================
    // Real enforcement is server-side (ms_calendar.api.otp.enforce_otp_verification,
    // hooked to Field Registration Form's validate event) — this UI is just so
    // candidates don't hit that error only after clicking Submit. A guest could
    // bypass this via devtools, but they can't fake the server-side cache flag
    // without actually calling verify_otp/verify_email_otp with the right code.
    const RESEND_COOLDOWN_SECS = 60;
    const SEND_BTN_STYLE = "background:#1e3a8a;color:#fff;border:none;border-radius:6px;padding:6px 14px;font-size:12.5px;font-weight:600;cursor:pointer;";
    const VERIFY_BTN_STYLE = "background:#059669;color:#fff;border:none;border-radius:6px;padding:6px 14px;font-size:12.5px;font-weight:600;cursor:pointer;margin-left:6px;";

    function setup_otp_verification(fieldname, sendMethod, verifyMethod, otpArgKey, validateInput) {
        const wrapper = document.querySelector(`[data-fieldname="${fieldname}"]`);
        if (!wrapper) return () => false;
        const input = wrapper.querySelector("input");
        if (!input) return () => false;

        let verified = false;
        let cooldownTimer = null;

        const box = document.createElement("div");
        box.style.marginTop = "8px";
        box.innerHTML = `
            <button type="button" class="otp-send-btn" style="${SEND_BTN_STYLE}">Generate OTP</button>
            <span class="otp-status" style="margin-left:10px;font-size:12px;font-weight:600;"></span>
            <div class="otp-verify-row" style="display:none;margin-top:8px;">
                <input type="text" class="form-control otp-code-input" placeholder="Enter OTP" style="max-width:160px;display:inline-block;">
                <button type="button" class="otp-verify-btn" style="${VERIFY_BTN_STYLE}">Verify</button>
            </div>
        `;
        wrapper.appendChild(box);

        const sendBtn = box.querySelector(".otp-send-btn");
        const status = box.querySelector(".otp-status");
        const verifyRow = box.querySelector(".otp-verify-row");
        const codeInput = box.querySelector(".otp-code-input");
        const verifyBtn = box.querySelector(".otp-verify-btn");

        function set_status(msg, ok) {
            status.textContent = msg;
            status.style.color = ok ? "#059669" : "#c0392b";
        }

        function set_disabled(btn, disabled) {
            btn.disabled = disabled;
            btn.style.opacity = disabled ? "0.6" : "1";
            btn.style.cursor = disabled ? "not-allowed" : "pointer";
        }

        function stop_cooldown() {
            if (cooldownTimer) {
                clearInterval(cooldownTimer);
                cooldownTimer = null;
            }
        }

        function start_cooldown() {
            stop_cooldown();
            let remaining = RESEND_COOLDOWN_SECS;
            set_disabled(sendBtn, true);
            sendBtn.textContent = `Resend OTP (${remaining}s)`;
            cooldownTimer = setInterval(() => {
                remaining -= 1;
                if (remaining <= 0) {
                    stop_cooldown();
                    set_disabled(sendBtn, false);
                    sendBtn.textContent = "Resend OTP";
                } else {
                    sendBtn.textContent = `Resend OTP (${remaining}s)`;
                }
            }, 1000);
        }

        function reset_verified() {
            verified = false;
            stop_cooldown();
            set_status("", true);
            verifyRow.style.display = "none";
            sendBtn.style.display = "";
            set_disabled(sendBtn, false);
            sendBtn.textContent = "Generate OTP";
            input.readOnly = false;
            input.style.background = "";
        }

        input.addEventListener("input", () => { if (verified) reset_verified(); });

        sendBtn.addEventListener("click", () => {
            const value = input.value.trim();
            const err = validateInput(value);
            if (err) { set_status(err, false); return; }
            set_disabled(sendBtn, true);
            const wasResend = sendBtn.textContent.indexOf("Resend") === 0;
            sendBtn.textContent = "Sending...";
            frappe.call({
                method: sendMethod,
                args: { [otpArgKey]: value },
                callback: (r) => {
                    if (r.message && r.message.success) {
                        set_status(r.message.message || "OTP sent.", true);
                        verifyRow.style.display = "block";
                        start_cooldown();
                    } else {
                        set_disabled(sendBtn, false);
                        sendBtn.textContent = wasResend ? "Resend OTP" : "Generate OTP";
                        set_status((r.message && r.message.message) || "Failed to send OTP.", false);
                    }
                },
                error: () => {
                    set_disabled(sendBtn, false);
                    sendBtn.textContent = wasResend ? "Resend OTP" : "Generate OTP";
                    set_status("Failed to send OTP. Please try again.", false);
                },
            });
        });

        verifyBtn.addEventListener("click", () => {
            const value = input.value.trim();
            const code = codeInput.value.trim();
            if (!code) { set_status("Please enter the OTP.", false); return; }
            set_disabled(verifyBtn, true);
            frappe.call({
                method: verifyMethod,
                args: { [otpArgKey]: value, otp: code },
                callback: (r) => {
                    set_disabled(verifyBtn, false);
                    if (r.message && r.message.success) {
                        verified = true;
                        stop_cooldown();
                        verifyRow.style.display = "none";
                        sendBtn.style.display = "none";
                        status.innerHTML = `<span style="display:inline-flex;align-items:center;gap:5px;background:#dcfce7;color:#166534;border:1px solid #86efac;border-radius:999px;padding:4px 12px;font-size:12.5px;font-weight:700;">&#10003; Verified</span>`;
                        input.readOnly = true;
                        input.style.background = "#f0fdf4";
                        frappe.web_form.set_value(fieldname === "phone_number" ? "phone_verified" : "email_verified", 1);
                    } else {
                        set_status((r.message && r.message.message) || "Incorrect OTP.", false);
                    }
                },
                error: () => {
                    set_disabled(verifyBtn, false);
                    set_status("Verification failed. Please try again.", false);
                },
            });
        });

        return () => verified;
    }

    let isPhoneVerified = () => false;
    let isEmailVerified = () => false;

    setTimeout(() => {
        // PHONE OTP DISABLED — not ready yet, commented out (see ms_calendar.api.otp).
        // isPhoneVerified = setup_otp_verification(
        //     "phone_number",
        //     "ms_calendar.api.otp.send_otp",
        //     "ms_calendar.api.otp.verify_otp",
        //     "phone",
        //     (v) => (/^\d{10}$/.test(v) ? null : "Enter a valid 10-digit phone number.")
        // );
        isEmailVerified = setup_otp_verification(
            "email_address",
            "ms_calendar.api.otp.send_email_otp",
            "ms_calendar.api.otp.verify_email_otp",
            "email",
            (v) => (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) ? null : "Enter a valid email address.")
        );
    }, 500);

    frappe.web_form.validate = () => {
        // PHONE OTP DISABLED — not ready yet, commented out (see ms_calendar.api.otp).
        // if (!isPhoneVerified()) {
        //     frappe.msgprint("Please verify your phone number with the OTP before submitting.");
        //     return false;
        // }
        if (!isEmailVerified()) {
            frappe.msgprint("Please verify your email address with the OTP before submitting.");
            return false;
        }
        return true;
    };
};
